                listOf(must("""foreach\s*\(""", "Нужен цикл foreach (var x in nums)"), must("""Console\.WriteLine\s*\(""", "Выводи через Console.WriteLine(...)"), must("""\x24\x22""", "Интерполяция: строка начинается с знака доллара и кавычки"))),
