                listOf(must("""\?[^?:\n]+:""", "Нужен тернарный оператор: условие ? значение1 : значение2"), must("""Console\.WriteLine\s*\(""", "Выведи результат через Console.WriteLine"), must("""age\s*(>=|>|<|<=)\s*18""", "Сравни возраст с 18"))),
